// Dockerfile for a Spring Boot app
FROM eclipse-temurin:17-jre-alpine

// Create app directory
WORKDIR /app

// Copy the JAR built by Maven/Gradle
COPY target/order-service-1.0.0.jar app.jar

// Expose port Spring Boot uses
EXPOSE 8080

// Run the application
ENTRYPOINT ["java", "-jar", "app.jar"]

// Build command: docker build -t order-service:1.0 .
// Run command: docker run -p 8080:8080 order-service:1.0

// Your Spring Boot app now runs in isolation
// with Java 17 guaranteed, regardless of host OS

// Step 1: Build the Spring Boot JAR
// Command: mvn clean package -DskipTests
// Output: target/customer-service-1.0.0.jar

// Step 2: Create Dockerfile
FROM eclipse-temurin:17-jre-alpine
WORKDIR /app
COPY target/customer-service-1.0.0.jar app.jar
EXPOSE 8080
ENTRYPOINT ["java", "-jar", "app.jar"]

// Step 3: Build the Docker image
// Command: docker build -t customer-service:1.0 .
// Tags the image as customer-service version 1.0

// Step 4: Test locally
// Command: docker run -p 8080:8080 customer-service:1.0
// Maps container port 8080 to host port 8080
// Test: curl http://localhost:8080/customers

// Step 5: Push to registry
// docker tag customer-service:1.0 myuser/customer-service:1.0
// docker push myuser/customer-service:1.0
// Now available for deployment anywhere

// Multi-stage Dockerfile for production
FROM eclipse-temurin:17-jdk-alpine AS builder
WORKDIR /app
COPY pom.xml .
COPY src ./src
RUN ./mvnw clean package -DskipTests

// Final production stage
FROM eclipse-temurin:17-jre-alpine
WORKDIR /app

// Create non-root user for security
RUN addgroup -S appgroup && adduser -S appuser -G appgroup
USER appuser

// Copy only the JAR from builder stage
COPY --from=builder /app/target/payment-service-1.0.0.jar app.jar

EXPOSE 8080
ENTRYPOINT ["java", "-jar", "app.jar"]

// This image is optimized: small (JRE not JDK),
// secure (non-root user), and cacheable (separate stages)
